(7294117, 1137243, 66267, '<td valign="top">this one makes me feel feelings.</td>', 'this one makes me feel feelings.', '2014-12-19 09:26:14.000000', NULL, 1),
(7294118, 1137432, 70661, '<td valign="top">Yes, it was quite the gathering. Everyone was there!</td>', 'Yes, it was quite the gathering. Everyone was there!', '2014-12-19 09:27:17.000000', NULL, 1),
(7294119, 1137338, 70661, '<td valign="top">I''m glad you captured the person walking.</td>', 'I''m glad you captured the person walking.', '2014-12-19 09:28:48.000000', NULL, 1),
(7294120, 1137458, 43565, '<td valign="top">To me, this just looks blurry rather than painted. There is not enough of the kitchen showing to make it interesting, leaving the background to become a distraction (especially the door knob and blown out area). Her pose looks interesting, but would like to see more of her.</td>', 'To me, this just looks blurry rather than painted. There is not enough of the kitchen showing to make it interesting, leaving the background to become a distraction (especially the door knob and blown out area). Her pose looks interesting, but would like to see more of her.', '2014-12-19 09:34:02.000000', NULL, 1),
