(7294874, 1137348, 70661, '<td valign="top">One of my fav''s.</td>', 'One of my fav''s.', '2014-12-22 08:41:08.000000', NULL, 1),
(7294875, 1137356, 70661, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2014-12-22 08:41:36.000000', NULL, 1),
(7294899, 1137423, 30861, '<td valign="top">It''s a pleasant image, but it doesn''t really respond to the challenge IMO. That is to say, there''s nothing particularly "painterly" about it. One area in which the image falls short, both as a painting and as a photograph, is in the very flat lighting, which seems to be coming from behind you. It''s rare to see a landscape painting made "downsun" like this, for good reason; the painter has the option to use light to model her surfaces and give dimensionality to her work.</td>', 'It''s a pleasant image, but it doesn''t really respond to the challenge IMO. That is to say, there''s nothing particularly "painterly" about it. One area in which the image falls short, both as a painting and as a photograph, is in the very flat lighting, which seems to be coming from behind you. It''s rare to see a landscape painting made "downsun" like this, for good reason; the painter has the option to use light to model her surfaces and give dimensionality to her work.', '2014-12-22 10:32:58.000000', NULL, 1),
(7295131, 1137414, 114225, '<td valign="top">This is fantastic.</td>', 'This is fantastic.', '2014-12-23 10:13:54.000000', NULL, 1),
