(7295165, 1137357, 150277, '<td valign="top">Very poetic and lovely.  The subtle lighting and reflection make the shot for me.</td>', 'Very poetic and lovely.  The subtle lighting and reflection make the shot for me.', '2014-12-23 13:30:19.000000', NULL, 1),
